//! Golden vectors shared with the JavaScript client. The file is generated by this test
//! (`VELQRA_WRITE_VECTORS=1 cargo test -p velqra-bridge --test vectors`) and otherwise verified, so
//! the two implementations cannot drift apart unnoticed.
use serde_json::json;
use velqra_bridge::handshake::*;
use velqra_bridge::secret::InstallSecret;
use velqra_protocol::*;

const PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../extension/test/vectors.json"
);

fn vectors() -> serde_json::Value {
    let mut key = [0u8; 32];
    for (i, b) in key.iter_mut().enumerate() {
        *b = i as u8;
    }
    let secret = InstallSecret::from_bytes(key);
    let (cn, sn, core) = ([1u8; 16], [2u8; 16], [3u8; 16]);
    let origin = "chrome-extension://aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/";
    let f = Fields {
        cn: &cn,
        sn: &sn,
        origin: origin.as_bytes(),
        core: &core,
    };
    let b64: Vec<_> = ["", "f", "fo", "foo", "foob", "fooba", "foobar"]
        .iter()
        .map(|p| json!({"plain": p, "encoded": b64_encode(p.as_bytes())}))
        .collect();
    let rr = RequestRef {
        task_id: 7,
        fingerprint: "ab".repeat(32),
    };
    let env = |id: &str, body: Message| -> serde_json::Value {
        let e = Envelope {
            version: PROTOCOL_VERSION,
            message_id: id.to_string(),
            session_id: "0123456789abcdef0123456789abcdef".to_string(),
            request_id: "req-1".to_string(),
            generation: 1,
            body,
        };
        serde_json::from_slice(&e.encode().unwrap()).unwrap()
    };
    let prepare = PrepareBody {
        download_key: "d1".into(),
        url: "https://x.test/a.zip".into(),
        filename: "a.zip".into(),
        context: Secret("ctx".into()),
    };
    let envelopes = json!({
        "prepare": env("m1", Message::Prepare(prepare)),
        "begin_handoff": env("m2", Message::BeginHandoff(rr.clone())),
        "commit": env("m3", Message::Commit(CommitBody { cancel: CancelEvidence::Confirmed, receipt: rr.clone() })),
        "abort": env("m4", Message::Abort(AbortBody { receipt: Some(rr.clone()) })),
        "abort_unknown": env("m5", Message::Abort(AbortBody { receipt: None })),
        "reconcile": env("m6", Message::Reconcile(ReconcileBody { owner: OwnerEvidence::Unknown, receipt: rr })),
        "status": env("m7", Message::Status(Empty {})),
        "health": env("m8", Message::Health(Empty {})),
    });
    json!({
        "envelopes": envelopes,
        "secret_b64": b64_encode(&key),
        "cn_b64": b64_encode(&cn),
        "sn_b64": b64_encode(&sn),
        "core_b64": b64_encode(&core),
        "origin": origin,
        "server_mac_b64": b64_encode(&mac(&secret, LABEL_SERVER, &f)),
        "client_mac_b64": b64_encode(&mac(&secret, LABEL_CLIENT, &f)),
        "server_transcript_b64": b64_encode(&transcript(LABEL_SERVER, &f)),
        "hmac_rfc4231_case2_hex": "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843",
        "base64": b64,
    })
}

#[test]
fn the_committed_vectors_match_the_rust_implementation() {
    let want = serde_json::to_string_pretty(&vectors()).unwrap() + "\n";
    if std::env::var("VELQRA_WRITE_VECTORS").is_ok() {
        std::fs::write(PATH, &want).unwrap();
    }
    let have = std::fs::read_to_string(PATH).expect("run once with VELQRA_WRITE_VECTORS=1");
    assert_eq!(have.replace("\r\n", "\n"), want, "vectors.json is stale");
}
